/* From Uiverse.io by omar-alghaish - Tags: login, form */
.__UIV_SCOPE__ .form-container {
  width: 300px;
  background: linear-gradient(180deg,rgb(0, 183, 255) 25%,rgb(255, 255, 255) 20%);
  height: 350px;
  display: flex;
  flex-direction: column;
  justify-content: center;
  align-items: center;
  position: relative;
}

.__UIV_SCOPE__ .form {
  width: 80%;
  display: flex;
  flex-direction: column;
  margin-top: 40px;
}

.__UIV_SCOPE__ .form-container p {
  position: absolute;
  top: 10%;
  left: 10%;
  font-size: 30px;
  font-weight: 900;
  color: rgb(255, 255, 255);
}

.__UIV_SCOPE__ .form-container label {
  color: rgb(40, 42, 44);
  margin-top: 15px;
  margin-bottom: 5px;
  font-size: 15px;
}

.__UIV_SCOPE__ .form-container .input {
  padding: 10px;
  height: 35px;
  border: none;
  background-color: rgb(224, 231, 236);
}

.__UIV_SCOPE__ .form-container .input:focus {
  outline: none;
}

.__UIV_SCOPE__ .form-container button {
  border: none;
  height: 35px;
  margin-top: 30px;
  background-color: rgb(0, 183, 255);
  color: white;
  font-size: 16px;
}
